-- Trails become a treat to save up for (Phase 17.1): a trail opens once you've discovered 5
-- places in its city (TRAIL_UNLOCK_AFTER, the same step as hidden gems) and then costs 300 coins
-- to start (TRAIL_UNLOCK_COINS). Starting again later resumes for free. A perfect run pays back
-- up to 150 coins, so trails also keep coins meaningful. Coins are never sold: you earn them.
-- Two Lisbon trails join the two in Sintra (content below, generated by trailsSql()).

-- Places you've discovered in a region (visits are one per place).
create or replace function public.discoveries_in_region(uid uuid, p_region uuid)
returns integer language sql stable security definer set search_path = public, pg_temp as $$
  select count(*)::integer from public.visits v join public.places p on p.id = v.place_id
  where v.user_id = uid and p.region_id = p_region
$$;
revoke execute on function public.discoveries_in_region(uuid, uuid) from public, anon, authenticated;

-- Unlock (5 discoveries in the city, then 300 coins) or resume a trail. Idempotent: a trail you've
-- started never charges again. Raises unknown_trail, locked or insufficient_coins.
create or replace function public.start_trail(p_trail text)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
declare
  uid uuid := auth.uid();
  t public.trails;
  balance integer;
begin
  if uid is null then raise exception 'not_authenticated' using errcode = 'P0001'; end if;
  select * into t from public.trails where slug = p_trail and is_active;
  if not found then raise exception 'unknown_trail' using errcode = 'P0001'; end if;
  -- Serialise per player so two taps can't spend the same coins twice.
  perform 1 from public.profiles where id = uid for update;
  if exists (select 1 from public.trail_progress where user_id = uid and trail_id = t.id) then
    return;
  end if;
  if public.discoveries_in_region(uid, t.region_id) < 5 then
    raise exception 'locked' using errcode = 'P0001';
  end if;
  select coalesce(sum(points), 0) into balance from public.points_ledger where user_id = uid;
  if balance < 300 then
    raise exception 'insufficient_coins' using errcode = 'P0001';
  end if;
  insert into public.points_ledger (user_id, kind, points, xp, ref_id, breakdown)
  values (uid, 'purchase', -300, 0, t.id, jsonb_build_object('trail', t.slug));
  insert into public.trail_progress (user_id, trail_id) values (uid, t.id);
end;
$$;

-- my_trails now also says how many places you've found in each trail's city.
drop function public.my_trails();
create function public.my_trails()
returns table (slug text, region_slug text, title text, intro text, outro text, theme text,
               started_at timestamptz, completed_at timestamptz, discoveries integer, stops jsonb)
language sql stable security definer set search_path = public, pg_temp as $$
  select t.slug, r.slug, t.title, t.intro, t.outro, t.theme::text, tp.started_at, tp.completed_at,
         case when auth.uid() is null then 0 else public.discoveries_in_region(auth.uid(), t.region_id) end,
         coalesce((
           select jsonb_agg(jsonb_build_object(
                    'position', s.position,
                    'place_id', s.place_id,
                    'place_name', p.name,
                    'lat', extensions.st_y(p.location::extensions.geometry),
                    'lng', extensions.st_x(p.location::extensions.geometry),
                    'story', s.story,
                    'question', s.question,
                    'kind', s.kind,
                    'choices', s.choices,
                    'hints', coalesce(sec.hints[1:coalesce(sp.hints_used, 0)], '{}'),
                    'wrong', coalesce(sp.wrong, 0),
                    'solved', sp.solved_at is not null,
                    'coins', sp.coins,
                    'discovered', exists (select 1 from public.visits v
                                          where v.user_id = auth.uid() and v.place_id = s.place_id))
                  order by s.position)
           from public.trail_stops s
           join public.places p on p.id = s.place_id
           join public.trail_secrets sec on sec.trail_id = s.trail_id and sec.position = s.position
           left join public.trail_stop_progress sp
             on sp.user_id = auth.uid() and sp.trail_id = s.trail_id and sp.position = s.position
           where s.trail_id = t.id), '[]'::jsonb) as stops
  from public.trails t
  join public.regions r on r.id = t.region_id
  left join public.trail_progress tp on tp.trail_id = t.id and tp.user_id = auth.uid()
  where t.is_active
  order by t.position;
$$;
grant execute on function public.my_trails() to anon, authenticated;

